package net.civeira.phylax.feature.access.userscopeconsent.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClientReference;

class OauthClientVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property oauth client of user scope consent ")
  void test_oauth_client_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", OauthClientVO.fromReference("10").getOauthClientUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("11", OauthClientVO.tryFromReference("11").getOauthClientUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("12", OauthClientVO.tryFromReference("12", fails).getOauthClientUid(),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertThrows(ConstraintException.class, () -> OauthClientVO.tryFrom(null));
    Assertions.assertEquals(OauthClientReference.of("one"),
        OauthClientVO.from(OauthClientReference.of("one")).getOauthClient());
    Assertions.assertThrows(ConstraintException.class,
        () -> OauthClientVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + OauthClientReference.of("one") + "]",
        OauthClientVO.from(OauthClientReference.of("one")).toString());
  }
}
